export type ScribbleKey =
  | 'blueScribble'
  | 'blueSwoosh'
  | 'blueSwooshSmall'
  | 'blushHighlight'
  | 'fuchsiaHighlight'
  | 'greenSwoosh'
  | 'limeHighlight'
  | 'limeSwoosh'
  | 'orangeCloud'
  | 'orangeStarburst'
  | 'periwinkleHighlight'
  | 'pinkLoops'
  | 'pinkOval'
  | 'pinkStarburst'
  | 'purpleSwoosh'
  | 'skyHighlight'
  | 'sunshineHighlight'
  | 'violetHighlight'
  | 'yellowLoops'
  | 'yellowOval'
  | 'yellowSpiral'
  | 'yellowSwoosh';

